        address[] memory tos = new address[](1);
        tos[0] = to;
        vm.prank(from);
        bool ok = c.transfer(from, address(tok), tos, v);
        assertTrue(ok, "successful batch transfer must return true");
    }
}

contract GoodToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    fallback() external payable {}
